-- PT115-S2-Q17. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT115-S2-Q17$batch04$ AND q.stimulus=$batch04$Columnist: Over the last 20 years the demand in North America for Japanese-made automobiles has increased, whereas the Japanese demand for North American-made automobiles has been stagnant. Until recently, this imbalance could plausibly be attributed to Japanese models’ superior fuel efficiency and reliability, but now cars made in North America are by these standards the equal of any Japanese model. What North American exporters continue to ignore is that the Japanese drive on the left side of the road. Therefore, one obstacle to reducing the automotive trade imbalance will be removed if North American manufacturers simply produce more cars with right-side steering wheels.$batch04$ AND q.prompt=$batch04$Which one of the following is an assumption required by the columnist's argument?$batch04$ AND q.correct_choice=$batch04$B$batch04$) THEN RAISE EXCEPTION 'Question changed: PT115-S2-Q17'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT115-S2-Q17$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S2-Q17'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT115-S2-Q17$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$Producing more cars with right-side steering wheels would remove one obstacle to reducing the automotive trade imbalance.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$The Japanese buy few North American cars. Fuel efficiency and reliability used to explain this, but North American cars now match Japanese ones on both. The Japanese drive on the left side of the road.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The columnist assumes driving on the left matters to Japanese buyers. If left-side steering wheels don't put them off, switching sides removes nothing.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A link: driving on the left makes the Japanese less inclined to buy cars with left-side steering wheels.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT115-S2-Q17$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$The argument relies on North American cars being equal *now*. It does not need them to keep improving.$batch04$), ($batch04$B$batch04$, $batch04$Negate it: Japanese drivers *are* inclined to buy left-side-wheel cars even though they drive on the left. Then the steering wheel is no obstacle, and switching it removes nothing.$batch04$), ($batch04$C$batch04$, $batch04$A legal requirement would make the point even stronger, but the argument only needs buyers to prefer right-side wheels.$batch04$), ($batch04$D$batch04$, $batch04$Removing *one obstacle* does not require most Japanese buyers to prefer the North American model.$batch04$), ($batch04$E$batch04$, $batch04$The argument does not claim this is the *only* way to reduce the imbalance.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT115-S2-Q17$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
